jsonTools.init:
function init(eli) {
  eli = eli || window.eli;
  if (!eli || !eli.register) return;

  // 2026-06-09: opened to all users (was andrew-only alpha). The strip
  // is OFF by default — users opt in via the 🧩 manager (tile or
  // Settings → Interface → Dashboard Widgets).

  // ── Kill switch ───────────────────────────────────────────────────
  try {
    eli.settings.register("dashboard_widgets_enabled", {
      default: true, type: "boolean", adminPushable: true,
      describe: "Dashboard widgets strip enabled",
    });
  } catch (_) {}
  function _featureOn() {
    try { return eli.settings.get("dashboard_widgets_enabled") !== false; }
    catch (_) { return true; }
  }

  // ── Layout persistence — config store, canonical {key, value} shape ─
  var LAYOUT_KEY = "widget_layout";
  var _layout = null; // { master, enabled:{}, order:[], sizes:{} }
  // Hard cap — exactly two widget boxes side by side, so the
  // dashboard's vertical height never changes with widget count.
  var MAX_ACTIVE = 2;
  function _defaultLayout() {
    return {
      // master:false — widgets are opt-in. First visit to the manager
      // flips the master toggle; word + trivia light up immediately.
      master: false,
      enabled: { word_day: true, trivia_day: true, joke_day: false },
      order: ["word_day", "trivia_day", "joke_day"],
      sizes: {},
    };
  }
  function _activeCount() {
    if (!_layout) return 0;
    var n = 0;
    _layout.order.forEach(function (id) {
      if (_layout.enabled[id] && _findWidget(id)) n++;
    });
    return n;
  }
  function _loadLayout() {
    return eli.storage.get("config", LAYOUT_KEY).then(function (row) {
      var v = (row && row.value) || {};
      var d = _defaultLayout();
      _layout = {
        master:  v.master === undefined ? d.master : !!v.master,
        enabled: v.enabled || d.enabled,
        order:   Array.isArray(v.order) && v.order.length ? v.order : d.order,
        sizes:   v.sizes || {},
      };
      return _layout;
    }).catch(function () { _layout = _defaultLayout(); return _layout; });
  }
  function _saveLayout() {
    return eli.storage.put("config", { key: LAYOUT_KEY, value: _layout, updatedAt: Date.now() })
      .catch(function () {});
  }

  // ── Deterministic daily index — same item all day, rotates at local
  //    midnight. Whole team would see the same item (shared watercooler).
  function _dayIndex(len, salt) {
    if (!len) return 0;
    var now = new Date();
    var start = new Date(now.getFullYear(), 0, 0);
    var doy = Math.floor((now - start) / 86400000);
    return (doy + (salt || 0)) % len;
  }
  function _esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }

  // ── Content: Word of the Day ──────────────────────────────────────
  var WORDS = [
    { t: "Force Majeure", d: "Excuses performance when extraordinary events beyond the parties' control intervene.", w: "List the triggering events — courts read these clauses narrowly." },
    { t: "Indemnification", d: "One party's promise to cover another's losses from specified claims.", w: "Watch the trio: scope, cap, and defense obligation — each is negotiated separately." },
    { t: "Novation", d: "Replacing a party (or obligation) with a new one, extinguishing the original.", w: "Unlike assignment, novation needs everyone's consent — including the party staying put." },
    { t: "Estoppel", d: "Bars a party from contradicting what it previously asserted when others relied on it.", w: "Your emails during a deal can estop your litigation position later." },
    { t: "Contra Proferentem", d: "Ambiguity is construed against the party that drafted it.", w: "The hidden tax on sloppy drafting — and a reason templates get audited." },
    { t: "Quantum Meruit", d: "Recovery of the reasonable value of services when no enforceable contract covers them.", w: "It's the fallback when work started before the contract was signed." },
    { t: "Severability", d: "If one clause fails, the rest of the agreement survives.", w: "Without it, one unenforceable term can take the whole contract down." },
    { t: "Consideration", d: "The bargained-for exchange that makes a promise enforceable.", w: "Recitals of $1 usually work — past consideration usually doesn't." },
    { t: "Peppercorn", d: "Nominal consideration — trivially small but legally sufficient.", w: "Courts ask whether consideration exists, not whether the deal was wise." },
    { t: "Condition Precedent", d: "An event that must occur before a duty to perform arises.", w: "Spot the difference between a promise (breach = damages) and a condition (no duty at all)." },
    { t: "Liquidated Damages", d: "Pre-agreed damages for a specific breach.", w: "Enforceable as a reasonable estimate — struck down as a penalty if punitive." },
    { t: "Integration Clause", d: "Declares the written agreement the complete and final deal.", w: "It activates the parol evidence rule — side emails stop counting." },
    { t: "Tolling", d: "Pausing the running of a limitations period.", w: "Tolling agreements buy negotiation time without losing claims." },
    { t: "Waiver", d: "Intentional relinquishment of a known right.", w: "'No-waiver' clauses exist because accepting late payment twice can waive timeliness." },
    { t: "Material Breach", d: "A failure serious enough to excuse the other side's performance.", w: "Materiality decides whether you can walk away or only sue for damages." },
    { t: "Cure Period", d: "Time given to fix a breach before remedies kick in.", w: "Notice-and-cure turns 'gotcha' terminations into negotiations." },
    { t: "Covenant", d: "A promise to do (affirmative) or not do (negative) something.", w: "Non-competes are negative covenants — scope and duration drive enforceability." },
    { t: "Recitals", d: "The 'whereas' clauses describing background and intent.", w: "Usually not binding — but courts read them when operative terms are ambiguous." },
    { t: "Counterparts", d: "Permits signing in separate copies that together form one agreement.", w: "The clause that quietly blesses scattered e-signatures." },
    { t: "Ipso Facto", d: "'By the fact itself' — clauses triggered automatically by an event, like bankruptcy.", w: "Ipso facto termination-on-bankruptcy clauses are largely unenforceable in bankruptcy." },
    { t: "Pari Passu", d: "'On equal footing' — obligations rank equally without preference.", w: "A lender phrase that migrates into IP and payment waterfall clauses." },
    { t: "Time Is of the Essence", d: "Makes timely performance a material term.", w: "Without it, 'late' is usually a damages problem, not a termination right." },
    { t: "Assignment", d: "Transferring contract rights to a third party.", w: "Anti-assignment clauses often carve out affiliates and M&A — read the carve-outs first." },
    { t: "Representations & Warranties", d: "Statements of fact (reps) and promises they're true (warranties).", w: "Reps support fraud claims; warranties support breach claims — survival periods differ." },
  ];

  // ── Content: Trivia of the Day ────────────────────────────────────
  var TRIVIA = [
    { q: "In Leonard v. Pepsico, a man sued for the Harrier jet shown in a Pepsi Points ad. The court held the ad was…", a: ["An obvious joke — no offer", "A binding unilateral offer", "An invitation to negotiate only"], c: 0, x: "The court found no objective person could believe a $23M fighter jet came with 7,000,000 Pepsi Points. The 'offer' failed as a matter of law." },
    { q: "A missing Oxford comma in a Maine dairy's overtime statute famously cost the company about…", a: ["$5 million", "$50,000", "$500 million"], c: 0, x: "O'Connor v. Oakhurst Dairy (2017) — 'packing for shipment or distribution' was ambiguous without the comma; the case settled for $5M." },
    { q: "Carlill v. Carbolic Smoke Ball Co. established that a public ad promising payment can be…", a: ["A unilateral offer accepted by performance", "Mere puffery, never binding", "Valid only if individually addressed"], c: 0, x: "Mrs. Carlill used the smoke ball, caught influenza anyway, and the £100 reward was enforceable — the ad was an offer to the world." },
    { q: "Van Halen's contracts demanded a bowl of M&Ms with the brown ones removed. The clause's real purpose was…", a: ["A safety-compliance canary", "Pure rock-star ego", "A merchandising tie-in"], c: 0, x: "Buried in dense technical riders, brown M&Ms revealed whether the venue had actually read the safety specs for their massive stage rig." },
    { q: "Hadley v. Baxendale limits consequential damages to losses that were…", a: ["Foreseeable at contract formation", "Actually suffered, however remote", "Under £100"], c: 0, x: "The broken mill shaft case (1854) — special circumstances must be communicated up front, which is why limitation-of-liability clauses recite them." },
    { q: "Under the mailbox rule, an acceptance is generally effective when…", a: ["Dispatched", "Received", "Read"], c: 0, x: "Acceptance on dispatch; revocation on receipt. Modern contracts often override it by requiring notice to be 'effective on receipt.'" },
    { q: "The Statute of Frauds generally requires a writing for contracts that cannot be performed within…", a: ["One year", "Six months", "Thirty days"], c: 0, x: "The one-year rule is read narrowly: if performance within a year is conceivably possible, no writing is required." },
    { q: "The UCC's 'battle of the forms' provision is…", a: ["§ 2-207", "§ 1-103", "§ 9-401"], c: 0, x: "It decides whose boilerplate wins when purchase orders and acknowledgments conflict — and why 'last shot' doctrine faded for goods." },
    { q: "A liquidated damages clause is unenforceable when a court finds it operates as…", a: ["A penalty", "An estimate", "A cap"], c: 0, x: "The test: reasonable forecast of hard-to-measure harm at formation. In terrorem amounts get struck." },
    { q: "Specific performance is most readily granted for contracts involving…", a: ["Land and unique goods", "Commodity sales", "Employment services"], c: 0, x: "Money damages suffice for fungibles; uniqueness makes them inadequate. Courts won't order people to work — that's involuntary servitude territory." },
    { q: "The parol evidence rule bars…", a: ["Prior agreements contradicting an integrated writing", "All oral testimony in contract cases", "Evidence of fraud"], c: 0, x: "It protects final writings from being rewritten by negotiation history — but fraud, ambiguity, and condition-precedent evidence still come in." },
    { q: "'Four corners' interpretation means a court looks…", a: ["Only at the document itself", "At industry custom first", "At the parties' emails"], c: 0, x: "If the writing is unambiguous, extrinsic evidence stays out. Ambiguity is the doorway through which everything else enters." },
    { q: "An option contract differs from a plain offer because it…", a: ["Is supported by consideration and irrevocable", "Must be in writing", "Cannot expire"], c: 0, x: "Paying to hold an offer open makes revocation a breach. Without consideration, offers are freely revocable before acceptance." },
    { q: "In contract law, a 'peppercorn' refers to…", a: ["Nominal but sufficient consideration", "A minor breach", "A boilerplate clause"], c: 0, x: "Courts don't weigh the adequacy of consideration — a peppercorn will do, which is why $1 recitals persist." },
    { q: "The 'mirror image' rule requires that an acceptance…", a: ["Match the offer exactly", "Be in the same medium as the offer", "Be notarized"], c: 0, x: "Any variation makes it a counteroffer at common law. The UCC relaxed this for goods — hence § 2-207's existence." },
    { q: "Promissory estoppel allows enforcement of a promise without…", a: ["Consideration", "Reliance", "A promisor"], c: 0, x: "Reasonable, detrimental reliance substitutes for the bargain. It's the safety net under gratuitous promises." },
    { q: "A contract signed under economic duress is…", a: ["Voidable by the coerced party", "Automatically void", "Fully enforceable"], c: 0, x: "Voidable, not void — the victim chooses whether to rescind, and ratification by performance can waive the defense." },
    { q: "'Efficient breach' theory says a party should breach when…", a: ["Paying damages costs less than performing", "The other side breaches first", "A better lawyer is available"], c: 0, x: "Law-and-economics' most provocative idea: expectation damages make some breaches socially efficient. Liquidated damages clauses push back." },
  ];

  // ── Content: Joke of the Day ──────────────────────────────────────
  var JOKES = [
    { s: "Why did the contract go to therapy?", p: "It had too many unresolved issues." },
    { s: "I'd tell you a confidentiality joke…", p: "…but you'd have to sign an NDA first." },
    { s: "What did the indemnification clause say at the party?", p: "\"Don't worry — I've got you covered.\"" },
    { s: "Why did the clause break up with the sentence?", p: "It needed more consideration." },
    { s: "What's a contract's favorite love story?", p: "An offer and an acceptance." },
    { s: "Why was the boilerplate so calm?", p: "Nothing ever changed it." },
    { s: "How does a contract say goodbye?", p: "\"Termination for convenience.\"" },
    { s: "Why did the warranty blush?", p: "It got disclaimed in ALL CAPS." },
    { s: "Why are amendments so polite?", p: "They always ask both parties before changing anything." },
    { s: "What's the integration clause's dating profile?", p: "\"Supersedes all prior relationships, written or oral.\"" },
    { s: "The statute of limitations walked into a bar…", p: "…eventually." },
    { s: "What's severability's motto?", p: "\"If one of us falls, the rest carry on.\"" },
    { s: "Why does force majeure never get invited to parties?", p: "It only shows up when everything goes wrong." },
    { s: "What's the most optimistic phrase in contract law?", p: "\"Best efforts.\"" },
    { s: "Why did the deadline say \"time is of the essence\"?", p: "Because nobody was taking it literally." },
    { s: "What did one redline say to the other?", p: "\"I don't think we're aligned.\"" },
    { s: "Why do recitals make terrible witnesses?", p: "Everything they say is non-binding." },
    { s: "What did the counterparty say to the 47-page MSA?", p: "\"Let's just say we're reviewing it.\"" },
    { s: "Why was the cure period feeling generous?", p: "It always gives people 30 more days." },
    { s: "How do you comfort a frustrated contract?", p: "\"There, there — impossibility excuses us all sometimes.\"" },
    { s: "Why did the e-signature feel unappreciated?", p: "People kept asking if it was \"really\" binding. (It is.)" },
  ];

  // ── Built-in widget registry ──────────────────────────────────────
  // External tools can add widgets later via eli.dispatch("widgets",
  // "register", spec) — same spec shape as these.
  var REGISTRY = [
    {
      id: "word_day", icon: "📖", title: "Word of the Day",
      desc: "One legal term each day — definition + why it matters.",
      sizes: ["compact"],
      render: function (mount /*, size */) {
        var w = WORDS[_dayIndex(WORDS.length, 0)];
        var el = document.createElement("div");
        el.className = "_eli3_dw_card _eli3_dw_card_ivory _eli3_dw_compact";
        el.innerHTML =
          '<div class="_eli3_dw_eyebrow">📖 Word of the Day</div>' +
          '<div class="_eli3_dw_term">' + _esc(w.t) + '</div>' +
          '<div class="_eli3_dw_def">' + _esc(w.d) + '</div>' +
          '<div class="_eli3_dw_why">💡 ' + _esc(w.w) + '</div>';
        mount.appendChild(el);
      },
    },
    {
      id: "trivia_day", icon: "⚖️", title: "Contract Trivia",
      desc: "Daily contract-law trivia — tap an answer to reveal the story.",
      sizes: ["compact"],
      render: function (mount /*, size */) {
        var t = TRIVIA[_dayIndex(TRIVIA.length, 7)];
        var el = document.createElement("div");
        el.className = "_eli3_dw_card _eli3_dw_card_ivory _eli3_dw_compact";
        // Reveal sits ABOVE the question/answers — the card is a fixed-
        // height scroll box, so a bottom-positioned result could land
        // out of view. Top placement + scroll-to-top guarantees the
        // verdict is always visible the moment an answer is tapped.
        el.innerHTML =
          '<div class="_eli3_dw_eyebrow">⚖️ Contract Trivia</div>' +
          '<div class="_eli3_dw_reveal" hidden></div>' +
          '<div class="_eli3_dw_q">' + _esc(t.q) + '</div>' +
          '<div class="_eli3_dw_answers"></div>';
        var ansZone = el.querySelector("._eli3_dw_answers");
        var reveal = el.querySelector("._eli3_dw_reveal");
        // Shuffle the display order deterministically by day so the
        // correct answer isn't always first.
        var idxs = [0, 1, 2];
        var rot = _dayIndex(3, 3);
        idxs = idxs.slice(rot).concat(idxs.slice(0, rot));
        idxs.forEach(function (ai) {
          var b = document.createElement("button");
          b.type = "button";
          b.className = "_eli3_dw_ans";
          b.textContent = t.a[ai];
          b.onclick = function () {
            Array.prototype.slice.call(ansZone.querySelectorAll("._eli3_dw_ans")).forEach(function (bb, i2) {
              bb.disabled = true;
              var origIdx = idxs[i2];
              if (origIdx === t.c) bb.classList.add("_eli3_dw_ans_right");
              else if (bb === b) bb.classList.add("_eli3_dw_ans_wrong");
            });
            reveal.hidden = false;
            reveal.innerHTML = (ai === t.c ? "✅ <b>Correct.</b> " : "❌ <b>Not quite.</b> ") + _esc(t.x);
            el.scrollTop = 0;   // snap to top so the verdict is in view
          };
          ansZone.appendChild(b);
        });
        mount.appendChild(el);
      },
    },
    {
      id: "joke_day", icon: "😄", title: "Contract Joke",
      desc: "One groaner a day. Punchline hidden until you ask for it.",
      sizes: ["compact"],
      render: function (mount /*, size */) {
        var j = JOKES[_dayIndex(JOKES.length, 13)];
        var el = document.createElement("div");
        el.className = "_eli3_dw_card _eli3_dw_card_ivory _eli3_dw_compact";
        el.innerHTML =
          '<div class="_eli3_dw_eyebrow">😄 Contract Joke of the Day</div>' +
          '<div class="_eli3_dw_setup">' + _esc(j.s) + '</div>' +
          '<button type="button" class="_eli3_dw_punch_btn">Reveal punchline</button>' +
          '<div class="_eli3_dw_punch" hidden>' + _esc(j.p) + '</div>';
        var btn = el.querySelector("._eli3_dw_punch_btn");
        var punch = el.querySelector("._eli3_dw_punch");
        btn.onclick = function () {
          btn.style.display = "none";
          punch.hidden = false;
        };
        mount.appendChild(el);
      },
    },
  ];
  function _findWidget(id) {
    for (var i = 0; i < REGISTRY.length; i++) if (REGISTRY[i].id === id) return REGISTRY[i];
    return null;
  }

  // ── Host render — fills the home slot ─────────────────────────────
  function _renderInto(mount) {
    if (!mount) return;
    mount.innerHTML = "";
    if (!_featureOn() || !_layout || _layout.master === false) return;
    var host = document.createElement("div");
    host.className = "_eli3_dw_host";
    // Tiny manage gear — quiet until hovered.
    var gear = document.createElement("button");
    gear.type = "button";
    gear.className = "_eli3_dw_gear";
    gear.title = "Manage widgets";
    gear.textContent = "⚙";
    gear.onclick = _openManager;
    host.appendChild(gear);
    var rendered = 0;
    _layout.order.forEach(function (id) {
      if (rendered >= MAX_ACTIVE) return;   // hard cap — two boxes max
      if (!_layout.enabled[id]) return;
      var w = _findWidget(id);
      if (!w) return;
      var size = _layout.sizes[id] || w.sizes[0];
      try { w.render(host, size); rendered++; } catch (e) {
        try { eli.log.event("widgets.render_failed", { id: id, msg: e && e.message }); } catch (_) {}
      }
    });
    if (!rendered) { mount.innerHTML = ""; return; }
    mount.appendChild(host);
  }
  var _lastMount = null;

  // ── Manager dialog — master toggle, per-widget enable/reorder/size ─
  function _openManager() {
    var rowsHtml = "";
    showEliDialog({
      variant: "neutral",
      size: "wide",
      scroll: "internal",
      icon: "🧩",
      title: "Dashboard Widgets",
      body: '<div id="_eli3_dw_mgr"></div>',
      buttons: [{
        label: "Done",
        cls: "btn-secondary",
        onclick: function (e, ov) {
          if (ov.parentNode) ov.parentNode.removeChild(ov);
          _refreshDashboard();
        },
      }],
      onMount: function (overlay) {
        var box = overlay.querySelector("#_eli3_dw_mgr");
        if (!box) return;
        function _paint() {
          box.innerHTML = "";
          // Master toggle row
          var master = document.createElement("div");
          master.className = "_eli3_dw_mgr_master";
          master.innerHTML =
            '<div class="_eli3_dw_mgr_master_lbl">Show widgets on dashboard</div>';
          var mtgl = document.createElement("input");
          mtgl.type = "checkbox";
          mtgl.checked = _layout.master !== false;
          mtgl.onchange = function () {
            _layout.master = mtgl.checked;
            _saveLayout();
          };
          master.appendChild(mtgl);
          box.appendChild(master);
          // Per-widget rows, in current order
          _layout.order.forEach(function (id, idx) {
            var w = _findWidget(id);
            if (!w) return;
            var row = document.createElement("div");
            row.className = "_eli3_dw_mgr_row";
            // Reorder buttons
            var up = document.createElement("button");
            up.type = "button"; up.className = "_eli3_dw_mgr_btn"; up.textContent = "↑";
            up.disabled = idx === 0;
            up.onclick = function () {
              _layout.order.splice(idx, 1);
              _layout.order.splice(idx - 1, 0, id);
              _saveLayout(); _paint();
            };
            var dn = document.createElement("button");
            dn.type = "button"; dn.className = "_eli3_dw_mgr_btn"; dn.textContent = "↓";
            dn.disabled = idx === _layout.order.length - 1;
            dn.onclick = function () {
              _layout.order.splice(idx, 1);
              _layout.order.splice(idx + 1, 0, id);
              _saveLayout(); _paint();
            };
            row.appendChild(up); row.appendChild(dn);
            // Title + desc
            var main = document.createElement("div");
            main.className = "_eli3_dw_mgr_main";
            main.innerHTML =
              '<div class="_eli3_dw_mgr_title">' + _esc(w.icon + " " + w.title) + '</div>' +
              '<div class="_eli3_dw_mgr_desc">' + _esc(w.desc) + '</div>';
            row.appendChild(main);
            // Size selector (only when the widget supports >1 size)
            if (w.sizes && w.sizes.length > 1) {
              var sel = document.createElement("select");
              sel.className = "_eli3_dw_mgr_size";
              w.sizes.forEach(function (sz) {
                var o = document.createElement("option");
                o.value = sz;
                o.textContent = sz.charAt(0).toUpperCase() + sz.slice(1);
                if ((_layout.sizes[id] || w.sizes[0]) === sz) o.selected = true;
                sel.appendChild(o);
              });
              sel.onchange = function () {
                _layout.sizes[id] = sel.value;
                _saveLayout();
              };
              row.appendChild(sel);
            }
            // Enable toggle — enforces the two-at-a-time cap so the
            // dashboard strip never grows past one fixed-height row.
            var tgl = document.createElement("input");
            tgl.type = "checkbox";
            tgl.checked = !!_layout.enabled[id];
            tgl.onchange = function () {
              if (tgl.checked && _activeCount() >= MAX_ACTIVE) {
                tgl.checked = false;
                try {
                  if (typeof showToast === "function") {
                    showToast("Only " + MAX_ACTIVE + " widgets at a time — turn one off first.", "warn");
                  }
                } catch (_) {}
                return;
              }
              _layout.enabled[id] = tgl.checked;
              _saveLayout();
            };
            row.appendChild(tgl);
            box.appendChild(row);
          });
        }
        _paint();
      },
    });
    void rowsHtml;
  }
  function _refreshDashboard() {
    // Re-render via the kernel's dashboard refresh so every slot
    // (including ours) repaints with the new layout.
    try {
      if (eli.dashboard && typeof eli.dashboard.refresh === "function") { eli.dashboard.refresh(); return; }
    } catch (_) {}
    if (_lastMount) _renderInto(_lastMount);
  }

  // ── Wire-up: load layout → register slot + dispatch channel ──────
  _loadLayout().then(function () {
    if (eli.dashboard && typeof eli.dashboard.registerHomeSlot === "function") {
      // position "below" = the _eli3_below_slots host (under the tile
      // grid's + button and its divider line). Order 20 puts the strip
      // directly beneath that line, above the session feed (order 50).
      eli.dashboard.registerHomeSlot("dashboard_widgets", function (opts) {
        _lastMount = opts.mount;
        _renderInto(opts.mount);
      }, { order: 20, position: "below" });
      // Slot registration happens after the first dashboard paint —
      // refresh once so widgets appear without a manual reload.
      _refreshDashboard();
    }
  });

  eli.register({
    tile: { app_dashboard_widgets: _openManager },
    tile_settings: { app_dashboard_widgets: _openManager },
    widgets: {
      // Returns true so dispatch callers (eli_settings' Manage Widgets
      // button) can distinguish "handled" from "tool not loaded" —
      // a bare _openManager reference returned undefined, which the
      // settings button misread as not-loaded and toasted an error
      // even though the dialog opened.
      openManager: function () { _openManager(); return true; },
      register: function (spec) {
        // External widget registration (future tools). Specs missing
        // required fields are rejected silently.
        if (!spec || !spec.id || typeof spec.render !== "function") return false;
        if (_findWidget(spec.id)) return false;
        REGISTRY.push({
          id: spec.id, icon: spec.icon || "🧩", title: spec.title || spec.id,
          desc: spec.desc || "", sizes: spec.sizes || ["standard"],
          render: spec.render,
        });
        if (_layout && _layout.order.indexOf(spec.id) === -1) {
          _layout.order.push(spec.id);
          if (_layout.enabled[spec.id] === undefined) {
            _layout.enabled[spec.id] = spec.defaultEnabled !== false;
          }
          _saveLayout();
        }
        return true;
      },
      refresh: _refreshDashboard,
    },
  });

  eli.log.event("tool", "dashboard_widgets_initialized", {});
}

