/* dashboard_widgets — daily widget strip on the home dashboard.
   Cards are "ivory letterpress on a navy desk" in dark mode (the
   default dashboard), with body.light-mode overrides so they sit
   correctly on the light dashboard too. */

/* Two fixed-height boxes side by side — ONE row, always. The cap on
   active widgets (2) plus the fixed card height means the dashboard's
   vertical rhythm never changes, regardless of widget content or
   interaction (trivia reveals scroll inside their box). */
/* ── TRUE vertical centering between the gold line and the feed ─────
   eli-activity bottom-pins the whole below-slots host with
   `margin-top: auto`, so ALL flexible space sits above this strip —
   no fixed margin can center it. Fix: when OUR slot is present, let
   the host grow into that space instead (flex: 1) and center our slot
   wrapper with auto margins; the feed stays pinned to the bottom
   because our auto margins absorb the slack symmetrically. Scoped
   with :has() so when widgets are off (empty slot isn't appended),
   eli-activity's original bottom-pinning applies untouched. */
._eli3_main ._eli3_below_slots:has(> ._eli3_home_slot[data-slot-id="dashboard_widgets"]) {
  margin-top: 0;
  flex: 1 1 auto;
  min-height: 0;
}
._eli3_below_slots > ._eli3_home_slot[data-slot-id="dashboard_widgets"] {
  margin-top: auto;
  margin-bottom: auto;
}

._eli3_dw_host {
  position: relative;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
  margin: 0 12px;   /* sides only — vertical centering via auto margins above */
}
/* A lone enabled widget spans the full row at the same height. */
._eli3_dw_host > div:only-of-type {
  grid-column: 1 / -1;
}

/* Quiet manage gear — top-right of the strip, barely-there until hover */
._eli3_dw_gear {
  position: absolute;
  top: -4px;
  right: -2px;
  z-index: 2;
  background: transparent;
  border: none;
  font-size: 12px;
  color: rgba(203, 213, 225, 0.45);
  cursor: pointer;
  padding: 4px 6px;
  border-radius: 4px;
  transition: color 0.15s, background 0.15s;
}
._eli3_dw_gear:hover {
  color: #c9a227;
  background: rgba(201, 162, 39, 0.12);
}
body.light-mode ._eli3_dw_gear { color: rgba(100, 116, 139, 0.5); }
body.light-mode ._eli3_dw_gear:hover { color: #b8901f; background: rgba(201, 162, 39, 0.10); }

/* ── Card base — ivory plate, FIXED compact height, internal scroll ─
   Compact is the ONLY density: every widget renders tight so the
   strip stays one slim fixed-height row. Content taller than the box
   (trivia reveals) scrolls inside it. */
._eli3_dw_card {
  border-radius: 8px;
  padding: 9px 12px;
  box-sizing: border-box;
  height: 138px;                 /* fixed — dashboard height stays put */
  overflow-y: auto;
  overflow-x: hidden;
  animation: _eli3DwRise 0.45s cubic-bezier(0.2, 0.7, 0.3, 1) both;
  scrollbar-width: thin;
  scrollbar-color: rgba(201, 162, 39, 0.4) transparent;
}
._eli3_dw_card::-webkit-scrollbar { width: 5px; }
._eli3_dw_card::-webkit-scrollbar-thumb {
  background: rgba(201, 162, 39, 0.35);
  border-radius: 3px;
}
._eli3_dw_card::-webkit-scrollbar-track { background: transparent; }
._eli3_dw_card_ivory {
  background:
    radial-gradient(120% 200% at 0% 0%, rgba(201, 162, 39, 0.08) 0%, transparent 45%),
    linear-gradient(180deg, #fffdf8 0%, #faf6ea 100%);
  border: 1px solid rgba(201, 162, 39, 0.35);
  border-top: 2px solid #c9a227;
  box-shadow: 0 4px 14px rgba(2, 6, 23, 0.35);
}
body.light-mode ._eli3_dw_card_ivory {
  border-color: #e2d9bd;
  border-top-color: #c9a227;
  box-shadow: 0 2px 8px rgba(15, 23, 42, 0.08);
}
._eli3_dw_compact { padding: 9px 12px; }

@keyframes _eli3DwRise {
  from { opacity: 0; transform: translateY(8px); }
  to   { opacity: 1; transform: none; }
}

/* ── Shared type ──────────────────────────────────────────────────── */
._eli3_dw_eyebrow {
  font: 700 8.5px/1 'Inter', 'Segoe UI', sans-serif;
  text-transform: uppercase;
  letter-spacing: 1.6px;
  color: #b8901f;
  margin-bottom: 4px;
}

/* ── Word of the Day ──────────────────────────────────────────────── */
._eli3_dw_term {
  font: 700 14px/1.2 'Georgia', 'Times New Roman', serif;
  color: #1e3a8a;
}
._eli3_dw_def {
  font: 400 11.5px/1.45 'Inter', 'Segoe UI', sans-serif;
  color: #334155;
  margin-top: 3px;
}
._eli3_dw_why {
  font: 400 italic 10.5px/1.4 'Georgia', serif;
  color: #64748b;
  margin-top: 6px;
  padding-top: 6px;
  border-top: 1px dashed rgba(201, 162, 39, 0.35);
}

/* ── Trivia ───────────────────────────────────────────────────────── */
._eli3_dw_q {
  font: 600 12px/1.4 'Inter', 'Segoe UI', sans-serif;
  color: #0f172a;
  margin-bottom: 7px;
}
._eli3_dw_answers {
  display: flex;
  flex-direction: column;
  gap: 5px;
}
._eli3_dw_ans {
  text-align: left;
  font: 500 11.5px/1.3 'Inter', 'Segoe UI', sans-serif;
  color: #1e3a8a;
  background: #ffffff;
  border: 1px solid #d8d2bd;
  border-radius: 6px;
  padding: 6px 9px;
  cursor: pointer;
  transition: border-color 0.15s, background 0.15s, transform 0.1s;
}
._eli3_dw_ans:hover:not(:disabled) {
  border-color: #c9a227;
  background: #fffbeb;
  transform: translateX(2px);
}
._eli3_dw_ans:disabled { cursor: default; opacity: 0.85; }
._eli3_dw_ans_right {
  border-color: #10b981 !important;
  background: #ecfdf5 !important;
  color: #047857 !important;
  opacity: 1 !important;
  font-weight: 700;
}
._eli3_dw_ans_wrong {
  border-color: #fca5a5 !important;
  background: #fef2f2 !important;
  color: #b91c1c !important;
}
._eli3_dw_reveal {
  font: 400 11.5px/1.5 'Inter', 'Segoe UI', sans-serif;
  color: #475569;
  margin: 0 0 8px;              /* sits ABOVE the question now */
  padding: 8px 10px;
  background: rgba(201, 162, 39, 0.07);
  border-left: 3px solid #c9a227;
  border-radius: 0 4px 4px 0;
}

/* ── Joke ─────────────────────────────────────────────────────────── */
._eli3_dw_setup {
  font: 600 12.5px/1.4 'Georgia', serif;
  color: #0f172a;
}
._eli3_dw_punch_btn {
  margin-top: 6px;
  font: 600 10px/1 'Inter', sans-serif;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: #b8901f;
  background: transparent;
  border: 1px dashed rgba(201, 162, 39, 0.5);
  border-radius: 4px;
  padding: 6px 10px;
  cursor: pointer;
  transition: all 0.15s;
}
._eli3_dw_punch_btn:hover {
  background: rgba(201, 162, 39, 0.10);
  border-style: solid;
}
._eli3_dw_punch {
  font: 700 italic 13px/1.45 'Georgia', serif;
  color: #1e3a8a;
  margin-top: 8px;
  animation: _eli3DwRise 0.3s ease-out both;
}

/* ── Manager dialog ───────────────────────────────────────────────── */
._eli3_dw_mgr_master {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 10px 12px;
  background: #f8fafc;
  border: 1px solid #e2e8f0;
  border-radius: 6px;
  margin-bottom: 10px;
}
._eli3_dw_mgr_master_lbl {
  font: 700 12px/1.2 'Inter', sans-serif;
  color: #0f172a;
}
._eli3_dw_mgr_row {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 9px 10px;
  background: #fff;
  border: 1px solid #e2e8f0;
  border-radius: 6px;
  margin-bottom: 6px;
}
._eli3_dw_mgr_btn {
  background: #f8fafc;
  border: 1px solid #cbd5e1;
  border-radius: 4px;
  font-size: 11px;
  padding: 3px 7px;
  cursor: pointer;
  color: #475569;
}
._eli3_dw_mgr_btn:hover:not(:disabled) { background: #f1f5f9; color: #0f172a; }
._eli3_dw_mgr_btn:disabled { opacity: 0.3; cursor: default; }
._eli3_dw_mgr_main { flex: 1; min-width: 0; }
._eli3_dw_mgr_title {
  font: 700 12px/1.2 'Inter', sans-serif;
  color: #0f172a;
}
._eli3_dw_mgr_desc {
  font-size: 10.5px;
  color: #64748b;
  margin-top: 2px;
}
._eli3_dw_mgr_size {
  font: 600 11px/1.2 'Inter', sans-serif;
  color: #0f172a;
  background: #fff;
  border: 1px solid #cbd5e1;
  border-radius: 4px;
  padding: 4px 6px;
}
